SELECT r.reportIdx, r.reporterIdx, r.reportedUserIdx, r.domainType, r.targetIdx, r.reportType, r.reportContent, TO_CHAR(r.reportDate, 'YYYY-MM-DD HH24:MI:SS') AS reportDate, r.processStatus, TO_CHAR(r.processDate, 'YYYY-MM-DD HH24:MI:SS') AS processDate, r.adminMemo, u1.userId AS reporterId, u1.nickname AS reporterName, u2.userId AS reportedUserId, u2.nickname AS reportedUserName FROM adminReport r JOIN users u1 ON r.reporterIdx = u1.userIdx JOIN users u2 ON r.reportedUserIdx = u2.userIdx
r.processStatus = #{processStatus}
AND r.domainType IN ('COMMUNITY', 'COMMUNITY_REPLY')
AND r.domainType = #{domainType}
AND (u1.userId LIKE '%' || #{kwd} || '%' OR u1.nickname LIKE '%' || #{kwd} || '%' OR u2.userId LIKE '%' || #{kwd} || '%' OR u2.nickname LIKE '%' || #{kwd} || '%')
ORDER BY r.reportIdx DESC OFFSET #{offset} ROWS FETCH FIRST #{size} ROWS ONLY

SELECT NVL(COUNT(*), 0) FROM adminReport r JOIN users u1 ON r.reporterIdx = u1.userIdx JOIN users u2 ON r.reportedUserIdx = u2.userIdx
r.processStatus = #{processStatus}
AND r.domainType IN ('COMMUNITY', 'COMMUNITY_REPLY')
AND r.domainType = #{domainType}
AND (u1.userId LIKE '%' || #{kwd} || '%' OR u1.nickname LIKE '%' || #{kwd} || '%' OR u2.userId LIKE '%' || #{kwd} || '%' OR u2.nickname LIKE '%' || #{kwd} || '%')

