UPDATE adminReport
SET processStatus = #{processStatus, jdbcType=INTEGER},
    processDate   = CURRENT_TIMESTAMP,
    adminMemo     = #{adminMemo, jdbcType=VARCHAR}
WHERE reportIdx = #{reportIdx, jdbcType=NUMERIC}
